import { createImageUrlBuilder, type SanityImageSource } from "@sanity/image-url";
import { env, sanityProjectId } from "../env";

const builder = createImageUrlBuilder({
  projectId: sanityProjectId,
  dataset: env.sanity.dataset,
});

/** Build a Sanity CDN URL for an image, respecting hotspot and crop. */
export function urlForImage(source: SanityImageSource) {
  return builder.image(source).auto("format").fit("max");
}

/**
 * A blur-up placeholder generated by the CDN. Twenty pixels wide is enough
 * for a convincing LQIP and costs about 300 bytes.
 */
export function blurDataUrl(source: SanityImageSource): string {
  return builder.image(source).width(20).quality(20).blur(30).auto("format").url();
}

export type { SanityImageSource };
